import React from 'react';
import { Bar, Pie } from 'react-chartjs-2';
import { Chart as ChartJS, CategoryScale, LinearScale, BarElement, ArcElement, Title, Tooltip, Legend } from 'chart.js';

// Chart.js වලට අදාළ elements register කිරීම
ChartJS.register(CategoryScale, LinearScale, BarElement, ArcElement, Title, Tooltip, Legend);

export default function ChartComponent({type}) {
  // 1. Teacher Performance data
  const teacherData = {
    labels: ['Mr. Silva', 'Ms. Perera', 'Mr. Fernado', 'Ms. Jayasurya', 'Mr. Kumar'],
    datasets: [{
      label: 'Performance',
      data: [4.5, 4.1, 3.5, 3.2, 2.8],
      backgroundColor: '#95f63b'
    }]
  };

  // 2. Class Distribution data
  const classData = {
    labels: ['Math', 'Science', 'English', 'History', 'IT'],
    datasets: [{
      data: [30, 25, 15, 20, 10],
      backgroundColor: ['#14b1a4', '#22c55e', '#f59e0b', '#ef4444', '#06b6d4']
    }]
  };

  // ඊට පස්සේ ඔයා ලියලා තියෙන return (...) කොටස එහෙමම තියෙන්න දෙන්න.
   return (
    <>
      {type === 'bar' ? <Bar data={teacherData} /> : // ChartComponent.jsx එකේ
<Pie 
  data={classData} 
  options={{
    responsive: true,
    plugins: {
      legend: {
        position: 'right', // මේකෙන් තමයි Subjects ටික දකුණු පැත්තට එන්නේ
        display: true
      }
    }
  }} 
 />}
    </>
  );
}
